"""Tokenizer for the MTL DSL, including logical-line joining."""
import re

from .errors import DSLSyntaxError

# Token kinds
IDENT = "IDENT"
NUMBER = "NUMBER"
STRING = "STRING"
DURATION = "DURATION"
OP = "OP"
NEWLINE = "NEWLINE"
EOF = "EOF"

_NUMBER_RE = re.compile(r"(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_SUFFIX_RE = re.compile(r"[A-Za-z0-9_]+")
_OPERATORS = ("<=", ">=", "==", "!=", "<", ">", "&", "|", "!",
              "(", ")", "[", "]", ",", "*", "+", "-", "/", "%",
              "{", "}", ":", "=", "@")
DURATION_UNITS = {"m": 60, "h": 3600, "d": 86400}


class Token:
    __slots__ = ("kind", "value", "line", "col")

    def __init__(self, kind, value, line, col):
        self.kind = kind
        self.value = value
        self.line = line
        self.col = col

    def is_op(self, *ops):
        return self.kind == OP and self.value in ops

    def is_ident(self, *names):
        return self.kind == IDENT and self.value in names

    def describe(self):
        if self.kind == EOF:
            return "end of input"
        if self.kind == NEWLINE:
            return "end of line"
        if self.kind == STRING:
            return f"string '{self.value}'"
        if self.kind == DURATION:
            return f"duration '{self.value[0]}{self.value[1]}'"
        return f"'{self.value}'"

    def __repr__(self):
        return f"Token({self.kind}, {self.value!r}, {self.line}:{self.col})"


def tokenize(source):
    """Turn DSL source into a list of tokens (with NEWLINE separators, ending in EOF)."""
    tokens = []
    for lineno, line in enumerate(source.splitlines(), start=1):
        _tokenize_line(line, lineno, tokens)
        tokens.append(Token(NEWLINE, "\n", lineno, len(line) + 1))
    last_line = tokens[-1].line if tokens else 1
    tokens.append(Token(EOF, None, last_line, 0))
    return tokens


def _tokenize_line(line, lineno, out):
    pos = 0
    n = len(line)
    while pos < n:
        ch = line[pos]
        col = pos + 1
        if ch in " \t\r\f\v":
            pos += 1
        elif ch == "#":
            return
        elif ch in "'\"":
            end = line.find(ch, pos + 1)
            if end < 0:
                raise DSLSyntaxError(f"line {lineno}:{col}: unterminated string literal")
            value = line[pos + 1:end]
            if "\\" in value:
                raise DSLSyntaxError(
                    f"line {lineno}:{col}: escape sequences are not allowed in string literals"
                )
            out.append(Token(STRING, value, lineno, col))
            pos = end + 1
        elif ch.isdigit() or (ch == "." and pos + 1 < n and line[pos + 1].isdigit()):
            pos = _lex_number(line, pos, lineno, out)
        elif ch.isalpha() or ch == "_":
            m = _IDENT_RE.match(line, pos)
            out.append(Token(IDENT, m.group(0), lineno, col))
            pos = m.end()
        else:
            for op in _OPERATORS:
                if line.startswith(op, pos):
                    out.append(Token(OP, op, lineno, col))
                    pos += len(op)
                    break
            else:
                raise DSLSyntaxError(f"line {lineno}:{col}: unexpected character {ch!r}")


def _lex_number(line, pos, lineno, out):
    col = pos + 1
    m = _NUMBER_RE.match(line, pos)
    text = m.group(0)
    end = m.end()
    suffix_m = _SUFFIX_RE.match(line, end)
    if suffix_m:
        suffix = suffix_m.group(0)
        if text.isdigit() and suffix in DURATION_UNITS:
            out.append(Token(DURATION, (int(text), suffix), lineno, col))
            return suffix_m.end()
        raise DSLSyntaxError(f"line {lineno}:{col}: invalid literal '{text}{suffix}'")
    if "." in text or "e" in text or "E" in text:
        out.append(Token(NUMBER, float(text), lineno, col))
    else:
        out.append(Token(NUMBER, int(text), lineno, col))
    return end


def split_statements(tokens):
    """Group tokens into logical statements, joining continuation lines.

    A NEWLINE does not end a statement when brackets are open, when the
    previous token is ',' or a lone leading 'aggregate', or when the next
    token is ','. Outside brackets, '{' ends the statement it closes (a block
    header) and '}' always forms a statement of its own.
    """
    statements = []
    current = []
    depth = 0
    for i, tok in enumerate(tokens):
        if tok.kind == EOF:
            break
        if tok.kind == NEWLINE:
            if not current:
                continue
            nxt = _next_significant(tokens, i + 1)
            continues = (
                depth > 0
                or current[-1].is_op(",")
                or (len(current) == 1 and current[0].is_ident("aggregate"))
                or (nxt is not None and nxt.is_op(","))
            )
            if not continues:
                statements.append(current)
                current = []
            continue
        if depth == 0 and tok.is_op("{"):
            current.append(tok)
            statements.append(current)
            current = []
            continue
        if depth == 0 and tok.is_op("}"):
            if current:
                statements.append(current)
            statements.append([tok])
            current = []
            continue
        if tok.is_op("(", "["):
            depth += 1
        elif tok.is_op(")", "]"):
            depth -= 1
            if depth < 0:
                raise DSLSyntaxError(f"line {tok.line}:{tok.col}: unbalanced '{tok.value}'")
        current.append(tok)
    if current:
        if depth > 0:
            raise DSLSyntaxError(f"line {current[0].line}: unclosed bracket in statement")
        statements.append(current)
    return statements


def _next_significant(tokens, start):
    for tok in tokens[start:]:
        if tok.kind == NEWLINE:
            continue
        if tok.kind == EOF:
            return None
        return tok
    return None
"""Recursive-descent parser turning DSL source into a Program."""
from . import dtypes
from .ast_nodes import (POST_AGG, PRE, AggItem, Aggregate, Apply, Binary, Calc, Call, Cast,
                        ColumnRef, FieldDecl, Filter, GroupBy, InExpr, Literal, ParamDecl,
                        Program, SchemaDecl, Unary, Window)
from .errors import DSLSyntaxError
from .functions import ARITY, STRING_PREDICATES, WINDOW_FUNCTIONS
from .lexer import DURATION, DURATION_UNITS, EOF, IDENT, NUMBER, STRING, Token
from .lexer import split_statements, tokenize

AGG_FUNCTIONS = ("average", "median", "sum", "count", "std", "var", "min", "max")
COMPARISON_OPS = ("<", "<=", ">", ">=", "==", "!=")
RESERVED = ("true", "false", "in")
TYPE_NAMES = (dtypes.STRING, dtypes.INT, dtypes.FLOAT, dtypes.BOOL, dtypes.TIMESTAMP)
STAGES = (PRE, POST_AGG)


def parse_program(source):
    """Parse a DSL file: either bare Part 1 statements or schema/pipeline blocks."""
    return _DocumentParser(split_statements(tokenize(source))).parse()


def _build_program(statements, **extra):
    row_ops, calcs, group_by, window, aggregate = [], [], None, None, None
    for stmt in statements:
        if isinstance(stmt, (Filter, Apply)):
            row_ops.append(stmt)
        elif isinstance(stmt, Calc):
            calcs.append(stmt)
        elif isinstance(stmt, GroupBy):
            if group_by is not None:
                raise DSLSyntaxError(f"line {stmt.line}: group_by may appear at most once")
            group_by = stmt
        elif isinstance(stmt, Window):
            if window is not None:
                raise DSLSyntaxError(f"line {stmt.line}: window may appear at most once")
            window = stmt
        elif isinstance(stmt, Aggregate):
            if aggregate is not None:
                raise DSLSyntaxError(f"line {stmt.line}: aggregate must appear exactly once")
            aggregate = stmt
    if aggregate is None:
        raise DSLSyntaxError("missing required aggregate statement")

    _check_output_names(group_by, aggregate, window, calcs)
    return Program(row_ops, group_by, window, aggregate, calcs=calcs, **extra)


def _check_output_names(group_by, aggregate, window, calcs):
    reserved = {"window_start", "window_end"} if window else set()
    taken = set()
    if group_by:
        for col in group_by.columns:
            if col in reserved:
                raise DSLSyntaxError(f"line {group_by.line}: group_by column '{col}' "
                                     "clashes with a window output field")
            taken.add(col)
    for item in aggregate.items:
        if item.alias in taken or item.alias in reserved:
            raise DSLSyntaxError(f"line {item.line}: output name '{item.alias}' is not unique")
        taken.add(item.alias)

    calc_names = set()
    for calc in calcs:
        if calc.name in calc_names:
            raise DSLSyntaxError(f"line {calc.line}: duplicate calc '{calc.name}'")
        calc_names.add(calc.name)
        if calc.stage == POST_AGG and (calc.name in taken or calc.name in reserved):
            raise DSLSyntaxError(f"line {calc.line}: calc '{calc.name}' collides with an "
                                 "existing output field")


class _DocumentParser:
    """Splits logical statements into schema blocks, one pipeline block, or bare statements."""

    def __init__(self, statements):
        self.statements = statements
        self.pos = 0

    def parse(self):
        schemas = {}
        pipeline = None
        loose = []
        while self.pos < len(self.statements):
            stmt = self._next()
            head = stmt[0]
            if head.is_ident("schema"):
                decl = self._parse_schema(stmt)
                if decl.name in schemas:
                    raise DSLSyntaxError(f"line {head.line}: duplicate schema '{decl.name}'")
                schemas[decl.name] = decl
            elif head.is_ident("pipeline"):
                if pipeline is not None:
                    raise DSLSyntaxError(f"line {head.line}: only one pipeline block is allowed")
                pipeline = self._parse_pipeline(stmt)
            elif head.is_op("{", "}"):
                _unexpected(head)
            else:
                loose.append(stmt)

        if not schemas and pipeline is None:
            return _build_program([_StatementParser(s).parse_statement() for s in loose])
        if loose:
            raise DSLSyntaxError(f"line {loose[0][0].line}: statements must appear inside "
                                 "the pipeline block")
        if pipeline is None:
            raise DSLSyntaxError("missing pipeline block")
        name, schema_name, params, body = pipeline
        if schema_name not in schemas:
            raise DSLSyntaxError(f"pipeline '{name}' uses unknown schema '{schema_name}'")
        return _build_program(body, params=params, schema_name=schema_name,
                              schemas=schemas, name=name)

    def _next(self):
        stmt = self.statements[self.pos]
        self.pos += 1
        return stmt

    def _header(self, stmt):
        """Return a block header's tokens without its opening '{'."""
        if stmt[-1].is_op("{"):
            return stmt[:-1]
        if self.pos < len(self.statements):
            nxt = self.statements[self.pos]
            if len(nxt) == 1 and nxt[0].is_op("{"):
                self.pos += 1
                return stmt
        last = stmt[-1]
        raise DSLSyntaxError(f"line {last.line}: expected '{{' after '{stmt[0].value}' header")

    def _block(self, opener):
        """Yield the statements of a block up to (and consuming) its closing '}'."""
        while self.pos < len(self.statements):
            stmt = self._next()
            if len(stmt) == 1 and stmt[0].is_op("}"):
                return
            yield stmt
        raise DSLSyntaxError(f"line {opener.line}: unclosed '{opener.value}' block")

    def _parse_schema(self, stmt):
        head = stmt[0]
        p = _StatementParser(self._header(stmt))
        p.advance()
        name = p.expect_ident("a schema name")
        base = None
        if p.tok.is_ident("extends"):
            p.advance()
            base = p.expect_ident("a base schema name")
            if p.tok.is_op(","):
                p.error("multiple inheritance is not allowed")
        p.expect_end()

        fields = []
        seen = set()
        for field_stmt in self._block(head):
            field = _StatementParser(field_stmt).parse_field()
            if field.name in seen:
                raise DSLSyntaxError(f"line {field.line}: duplicate field '{field.name}' "
                                     f"in schema '{name}'")
            seen.add(field.name)
            fields.append(field)
        return SchemaDecl(name, base, fields, head.line)

    def _parse_pipeline(self, stmt):
        head = stmt[0]
        p = _StatementParser(self._header(stmt))
        p.advance()
        name = p.expect_ident("a pipeline name")
        if not p.tok.is_ident("using"):
            p.error(f"expected 'using <SchemaName>' but found {p.tok.describe()}")
        p.advance()
        schema_name = p.expect_ident("a schema name")
        p.expect_end()

        params = None
        body = []
        for body_stmt in self._block(head):
            first = body_stmt[0]
            if first.is_ident("params") and (body_stmt[-1].is_op("{") or len(body_stmt) == 1):
                if params is not None:
                    raise DSLSyntaxError(f"line {first.line}: params may appear at most once")
                params = self._parse_params(body_stmt)
            elif first.is_ident("schema", "pipeline"):
                raise DSLSyntaxError(f"line {first.line}: '{first.value}' blocks cannot be nested")
            elif first.is_op("{", "}") or body_stmt[-1].is_op("{"):
                _unexpected(body_stmt[-1] if not first.is_op("{", "}") else first)
            else:
                body.append(_StatementParser(body_stmt).parse_statement())
        return name, schema_name, params or [], body

    def _parse_params(self, stmt):
        head = stmt[0]
        p = _StatementParser(self._header(stmt))
        p.advance()
        p.expect_end()
        params = []
        seen = set()
        for param_stmt in self._block(head):
            decl = _StatementParser(param_stmt).parse_param_decl()
            if decl.name in seen:
                raise DSLSyntaxError(f"line {decl.line}: duplicate parameter '{decl.name}'")
            seen.add(decl.name)
            params.append(decl)
        return params


def _unexpected(tok):
    raise DSLSyntaxError(f"line {tok.line}:{tok.col}: unexpected {tok.describe()}")


class _StatementParser:
    """Parses the tokens of one logical statement."""

    def __init__(self, tokens):
        self.tokens = tokens + [Token(EOF, None, tokens[-1].line, 0)]
        self.pos = 0

    # -- token helpers -------------------------------------------------
    @property
    def tok(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        if tok.kind != EOF:
            self.pos += 1
        return tok

    def error(self, message, tok=None):
        tok = tok or self.tok
        raise DSLSyntaxError(f"line {tok.line}:{tok.col}: {message}")

    def expect_op(self, op):
        if not self.tok.is_op(op):
            self.error(f"expected '{op}' but found {self.tok.describe()}")
        return self.advance()

    def expect_ident(self, what):
        tok = self.tok
        if tok.kind != IDENT or tok.value in RESERVED:
            self.error(f"expected {what} but found {tok.describe()}")
        return self.advance().value

    def expect_column(self, what="a column name"):
        """A column name, written bare or as a string literal."""
        if self.tok.kind == STRING:
            return self.advance().value
        return self.expect_ident(what)

    def expect_end(self):
        if self.tok.kind != EOF:
            self.error(f"unexpected {self.tok.describe()}")

    # -- statements ----------------------------------------------------
    def parse_statement(self):
        head = self.tok
        if head.kind != IDENT:
            self.error(f"expected a statement but found {head.describe()}")
        handler = {
            "filter": self.parse_filter,
            "apply": self.parse_apply,
            "group_by": self.parse_group_by,
            "window": self.parse_window,
            "aggregate": self.parse_aggregate,
            "calc": self.parse_calc,
        }.get(head.value)
        if handler is None:
            self.error(f"unknown statement '{head.value}'")
        self.advance()
        stmt = handler(head.line)
        self.expect_end()
        return stmt

    def parse_type(self):
        tok = self.tok
        if tok.kind != IDENT or tok.value not in TYPE_NAMES:
            self.error(f"expected a type ({', '.join(TYPE_NAMES)}) but found {tok.describe()}")
        self.advance()
        return tok.value

    def parse_field(self):
        """`name: type [= expr]` inside a schema block."""
        tok = self.tok
        name = self.expect_ident("a field name")
        self.expect_op(":")
        field_type = self.parse_type()
        expr = None
        if self.tok.is_op("="):
            self.advance()
            expr = self.parse_expr()
        self.expect_end()
        return FieldDecl(name, field_type, expr, tok.line)

    def parse_param_decl(self):
        """`name [: type] [= literal]` inside a params block."""
        tok = self.tok
        name = self.expect_ident("a parameter name")
        param_type = None
        default = None
        if self.tok.is_op(":"):
            self.advance()
            param_type = self.parse_type()
        if self.tok.is_op("="):
            self.advance()
            lit_tok = self.tok
            default = self.parse_unary()
            if not isinstance(default, Literal):
                self.error("parameter default must be a literal", lit_tok)
        self.expect_end()
        return ParamDecl(name, param_type, default, tok.line)

    def parse_calc(self, line):
        name = self.expect_ident("a calc name")
        self.expect_op("=")
        expr = self.parse_expr()
        self.expect_op(":")
        declared = self.parse_type()
        stage = PRE
        if self.tok.is_op("@"):
            self.advance()
            if not self.tok.is_ident("stage"):
                self.error(f"expected 'stage' after '@' but found {self.tok.describe()}")
            self.advance()
            self.expect_op("(")
            tok = self.tok
            if tok.kind != IDENT or tok.value not in STAGES:
                self.error(f"expected a stage (pre or post_agg) but found {tok.describe()}")
            self.advance()
            stage = tok.value
            self.expect_op(")")
        return Calc(name, expr, declared, stage, line)

    def parse_filter(self, line):
        self.expect_op("(")
        expr = self.parse_expr()
        self.expect_op(")")
        return Filter(expr, line)

    def parse_apply(self, line):
        self.expect_op("(")
        expr = self.parse_expr()
        self.expect_op(",")
        name = self.expect_ident("a new column name")
        self.expect_op(")")
        return Apply(expr, name, line)

    def parse_group_by(self, line):
        self.expect_op("(")
        if self.tok.is_op("["):
            self.advance()
            columns = [self.expect_column()]
            while self.tok.is_op(","):
                self.advance()
                columns.append(self.expect_column())
            self.expect_op("]")
        else:
            columns = [self.expect_column()]
        self.expect_op(")")
        if len(set(columns)) != len(columns):
            raise DSLSyntaxError(f"line {line}: duplicate column in group_by")
        return GroupBy(columns, line)

    def parse_window(self, line):
        self.expect_op("(")
        tok = self.tok
        if tok.is_ident("param"):
            call = self.parse_primary()
            if not isinstance(call, Call):
                self.error("expected param(\"<name>\") or a duration literal", tok)
            self.expect_op(")")
            return Window(None, None, None, line, param=call.args[0].value)
        if tok.kind != DURATION:
            self.error(f"expected a duration literal like 10m, 1h or 7d but found {tok.describe()}")
        self.advance()
        amount, unit = tok.value
        if amount <= 0:
            self.error("window duration must be positive", tok)
        self.expect_op(")")
        return Window(amount, unit, amount * DURATION_UNITS[unit], line)

    def parse_aggregate(self, line):
        items = [self.parse_agg_item()]
        while self.tok.is_op(","):
            self.advance()
            items.append(self.parse_agg_item())
        return Aggregate(items, line)

    def parse_agg_item(self):
        tok = self.tok
        if tok.kind != IDENT:
            self.error(f"expected an aggregate function but found {tok.describe()}")
        if tok.value not in AGG_FUNCTIONS:
            self.error(f"unknown aggregate function '{tok.value}'")
        self.advance()
        self.expect_op("(")
        if self.tok.is_op("*"):
            self.advance()
            column = None
        else:
            column = self.expect_column("a column name or '*'")
        self.expect_op(")")
        if not self.tok.is_ident("as"):
            self.error(f"expected 'as <alias>' but found {self.tok.describe()}")
        self.advance()
        alias = self.expect_ident("an alias")
        return AggItem(tok.value, column, alias, tok.line)

    # -- expressions ---------------------------------------------------
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.tok.is_op("|"):
            op = self.advance()
            left = Binary("|", left, self.parse_and(), op.line)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.tok.is_op("&"):
            op = self.advance()
            left = Binary("&", left, self.parse_not(), op.line)
        return left

    def parse_not(self):
        if self.tok.is_op("!"):
            op = self.advance()
            return Unary("!", self.parse_not(), op.line)
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        tok = self.tok
        if tok.kind == "OP" and tok.value in COMPARISON_OPS:
            self.advance()
            node = Binary(tok.value, left, self.parse_additive(), tok.line)
        elif tok.is_ident("in"):
            self.advance()
            node = InExpr(left, self.parse_additive(), tok.line)
        elif tok.is_ident(*STRING_PREDICATES):
            self.advance()
            node = Call(tok.value, [left, self.parse_additive()], tok.line)
        else:
            return left
        nxt = self.tok
        if ((nxt.kind == "OP" and nxt.value in COMPARISON_OPS)
                or nxt.is_ident("in", *STRING_PREDICATES)):
            self.error("comparisons cannot be chained; use parentheses and '&'")
        return node

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.tok.is_op("+", "-"):
            op = self.advance()
            left = Binary(op.value, left, self.parse_multiplicative(), op.line)
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.tok.is_op("*", "/", "%"):
            op = self.advance()
            left = Binary(op.value, left, self.parse_unary(), op.line)
        return left

    def parse_unary(self):
        if self.tok.is_op("-", "+"):
            op = self.advance()
            operand = self.parse_unary()
            if isinstance(operand, Literal) and dtypes.is_numeric(operand.type):
                value = -operand.value if op.value == "-" else operand.value
                return Literal(value, operand.type)
            return Unary(op.value, operand, op.line)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind == NUMBER:
            self.advance()
            return Literal(tok.value, dtypes.FLOAT if isinstance(tok.value, float) else dtypes.INT)
        if tok.kind == STRING:
            self.advance()
            return Literal(tok.value, dtypes.STRING)
        if tok.is_op("("):
            self.advance()
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        if tok.kind == IDENT:
            if tok.value in ("true", "false"):
                self.advance()
                return Literal(tok.value == "true", dtypes.BOOL)
            if tok.value == "in":
                self.error("unexpected 'in'")
            self.advance()
            if self.tok.is_op("("):
                return self.parse_call(tok)
            return ColumnRef(tok.value, tok.line)
        self.error(f"expected an expression but found {tok.describe()}")

    def parse_call(self, name_tok):
        name = name_tok.value
        if name == "cast":
            return self.parse_cast(name_tok)
        if name not in ARITY:
            self.error(f"unknown function '{name}'", name_tok)
        self.expect_op("(")
        args = []
        if not self.tok.is_op(")"):
            args.append(self.parse_expr())
            while self.tok.is_op(","):
                self.advance()
                args.append(self.parse_expr())
        self.expect_op(")")
        lo, hi = ARITY[name]
        if not lo <= len(args) <= hi:
            expected = str(lo) if lo == hi else f"{lo} to {hi}"
            self.error(f"{name}() takes {expected} argument(s), got {len(args)}", name_tok)
        if name == "param":
            if not (isinstance(args[0], Literal) and args[0].type == dtypes.STRING):
                self.error("param() expects a parameter name as a string literal", name_tok)
        elif name in WINDOW_FUNCTIONS:
            k = args[1]
            is_param = isinstance(k, Call) and k.name == "param"
            is_positive_int = (isinstance(k, Literal) and k.type == dtypes.INT and k.value > 0)
            if not (is_param or is_positive_int):
                self.error(f"{name}() offset must be a positive integer literal "
                           "or an int param()", name_tok)
        return Call(name, args, name_tok.line)

    def parse_cast(self, name_tok):
        self.expect_op("(")
        operand = self.parse_expr()
        if not self.tok.is_ident("as"):
            self.error(f"expected 'as <type>' in cast() but found {self.tok.describe()}")
        self.advance()
        target = self.parse_type()
        self.expect_op(")")
        return Cast(operand, target, name_tok.line)

"""Static type checking of a parsed Program against its typing environment.

Name problems that are structural (forward references, aggregate aliases in
pre-stage calcs, undeclared parameters, lag/lead outside post-aggregation)
are reported as DSL errors before an expression is typed; everything else
is a type error.
"""
from . import casts, dtypes, functions
from .ast_nodes import (Apply, Binary, Call, Cast, ColumnRef, Filter, InExpr, Literal,
                        Unary)
from .errors import DSLSyntaxError, TypeCheckError
from .lexer import DURATION_UNITS

ARITHMETIC_OPS = ("+", "-", "*", "/", "%")
COMPARISON_OPS = ("<", "<=", ">", ">=", "==", "!=")
LOGICAL_OPS = ("&", "|")
WINDOW_COLUMNS = ("window_start", "window_end")

_AGG_TYPES = {"count": dtypes.INT, "average": dtypes.FLOAT, "median": dtypes.FLOAT,
              "std": dtypes.FLOAT, "var": dtypes.FLOAT}


def check_program(program, schema, params=None):
    """Annotate expression types and validate the pipeline; return the final row schema.

    `schema` maps the input fields to their types; `params` maps declared
    parameter names to resolved ParamValues.
    """
    params = params or {}
    schema = dict(schema)
    aliases = {item.alias for item in program.aggregate.items}

    pre_calcs = program.pre_calcs
    for idx, calc in enumerate(pre_calcs):
        if calc.name in schema:
            raise DSLSyntaxError(f"line {calc.line}: calc '{calc.name}' collides with an "
                                 "existing field")
        check_names(calc.expr, schema, params, line=calc.line,
                    aliases=aliases, later={c.name for c in pre_calcs[idx + 1:]})
        check_declared(calc.name, calc.declared_type, infer(calc.expr, schema, params), calc.line)
        schema[calc.name] = calc.declared_type

    for op in program.row_ops:
        if isinstance(op, Filter):
            check_names(op.predicate, schema, params, line=op.line)
            t = infer(op.predicate, schema, params)
            if t != dtypes.BOOL:
                raise TypeCheckError(f"line {op.line}: filter predicate must be boolean, got {t}")
        elif isinstance(op, Apply):
            check_names(op.expr, schema, params, line=op.line)
            schema[op.column] = infer(op.expr, schema, params)

    for col in program.group_columns:
        if col not in schema:
            raise TypeCheckError(f"line {program.group_by.line}: unknown group_by column '{col}'")

    if program.window is not None:
        _resolve_window_param(program.window, params)
        ts_type = schema.get("timestamp")
        if ts_type != dtypes.TIMESTAMP:
            raise TypeCheckError(f"line {program.window.line}: window requires a 'timestamp' "
                                 f"column of type timestamp, got {ts_type}")

    for item in program.aggregate.items:
        if item.column is None:
            if item.func != "count":
                raise TypeCheckError(f"line {item.line}: {item.func}(*) is not allowed; "
                                     "only count(*) may use '*'")
            continue
        if item.column not in schema:
            raise TypeCheckError(f"line {item.line}: unknown column '{item.column}' in {item.func}()")
        col_type = schema[item.column]
        if item.func != "count" and not dtypes.is_numeric(col_type):
            raise TypeCheckError(f"line {item.line}: {item.func}({item.column}) requires a numeric "
                                 f"column, got {col_type}")

    output = output_schema(program, schema)
    post_calcs = program.post_calcs
    for idx, calc in enumerate(post_calcs):
        check_names(calc.expr, output, params, line=calc.line, allow_window=True,
                    later={c.name for c in post_calcs[idx + 1:]})
        check_declared(calc.name, calc.declared_type, infer(calc.expr, output, params), calc.line)
        output[calc.name] = calc.declared_type
    return schema


def output_schema(program, schema):
    """Types of the fields of an aggregated output row (before post-agg calcs)."""
    output = {}
    if program.window is not None:
        for col in WINDOW_COLUMNS:
            output[col] = dtypes.TIMESTAMP
    for col in program.group_columns:
        output[col] = schema[col]
    for item in program.aggregate.items:
        output[item.alias] = _AGG_TYPES.get(item.func) or schema[item.column]
    return output


def check_schema_calcs(resolved, params):
    """Type the calculated fields of a resolved schema against its own fields."""
    types = resolved.types
    for field in resolved.calc_order:
        check_names(field.expr, field.visible, params, line=field.line)
        check_declared(field.name, field.type, infer(field.expr, types, params), field.line)


def check_declared(name, declared, inferred, line):
    if not (declared == inferred or (declared == dtypes.FLOAT and inferred == dtypes.INT)):
        raise TypeCheckError(f"line {line}: '{name}' is declared {declared} but its "
                             f"expression has type {inferred}")


def _resolve_window_param(window, params):
    if window.param is None:
        return
    param = params.get(window.param)
    if param is None:
        raise DSLSyntaxError(f"line {window.line}: unknown parameter '{window.param}'")
    value = param.value
    if (param.type != dtypes.STRING or len(value) < 2 or not value[:-1].isdigit()
            or value[-1] not in DURATION_UNITS or int(value[:-1]) <= 0):
        raise TypeCheckError(f"line {window.line}: window parameter '{window.param}' must be a "
                             f"duration string like '1h', got {param.type} {value!r}")
    window.amount = int(value[:-1])
    window.unit = value[-1]
    window.seconds = window.amount * DURATION_UNITS[window.unit]


def walk(expr):
    """Yield every node of an expression tree (pre-order)."""
    stack = [expr]
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, Unary):
            stack.append(node.operand)
        elif isinstance(node, Binary):
            stack.extend((node.right, node.left))
        elif isinstance(node, InExpr):
            stack.extend((node.haystack, node.needle))
        elif isinstance(node, Call):
            stack.extend(reversed(node.args))
        elif isinstance(node, Cast):
            stack.append(node.operand)


def check_names(expr, visible, params, line, aliases=(), later=(), allow_window=False):
    """Report structural name errors; unknown plain columns are left to `infer`."""
    for node in walk(expr):
        if isinstance(node, ColumnRef) and node.name not in visible:
            if node.name in later:
                raise DSLSyntaxError(f"line {line}: '{node.name}' is referenced before "
                                     "it is declared")
            if node.name in aliases:
                raise DSLSyntaxError(f"line {line}: aggregate alias '{node.name}' cannot be "
                                     "used before aggregation")
        elif isinstance(node, Call):
            if node.name == "param" and node.args[0].value not in params:
                raise DSLSyntaxError(f"line {line}: unknown parameter '{node.args[0].value}'")
            if node.name in functions.WINDOW_FUNCTIONS and not allow_window:
                raise DSLSyntaxError(f"line {line}: {node.name}() is only allowed in "
                                     "@stage(post_agg) calcs")


def infer(expr, schema, params=None):
    expr.type = _infer(expr, schema, params or {})
    return expr.type


def _infer(expr, schema, params):
    if isinstance(expr, Literal):
        return expr.type
    if isinstance(expr, ColumnRef):
        if expr.name not in schema:
            raise TypeCheckError(f"line {expr.line}: unknown column '{expr.name}'")
        return schema[expr.name]
    if isinstance(expr, Unary):
        t = infer(expr.operand, schema, params)
        if expr.op == "!":
            if t != dtypes.BOOL:
                raise TypeCheckError(f"line {expr.line}: '!' requires a boolean operand, got {t}")
            return dtypes.BOOL
        if not dtypes.is_numeric(t):
            raise TypeCheckError(f"line {expr.line}: unary '{expr.op}' requires a number, got {t}")
        return t
    if isinstance(expr, Binary):
        return _infer_binary(expr, schema, params)
    if isinstance(expr, InExpr):
        return _infer_in(expr, schema, params)
    if isinstance(expr, Cast):
        source = infer(expr.operand, schema, params)
        if not casts.allowed(source, expr.target):
            raise TypeCheckError(f"line {expr.line}: cannot cast {source} to {expr.target}")
        return expr.target
    if isinstance(expr, Call):
        return _infer_call(expr, schema, params)
    raise AssertionError(f"unknown expression node {expr!r}")


def _infer_call(expr, schema, params):
    if expr.name == "param":
        name = expr.args[0].value
        if name not in params:
            raise DSLSyntaxError(f"line {expr.line}: unknown parameter '{name}'")
        expr.value = params[name].value
        return params[name].type
    arg_types = [infer(a, schema, params) for a in expr.args]
    if expr.name in functions.WINDOW_FUNCTIONS:
        if arg_types[1] != dtypes.INT:
            raise TypeCheckError(f"line {expr.line}: {expr.name}() offset must be an int, "
                                 f"got {arg_types[1]}")
        return arg_types[0]
    return functions.result_type(expr.name, arg_types, expr.line)


def _infer_binary(expr, schema, params):
    lt = infer(expr.left, schema, params)
    rt = infer(expr.right, schema, params)
    op = expr.op
    if op in LOGICAL_OPS:
        if lt != dtypes.BOOL or rt != dtypes.BOOL:
            raise TypeCheckError(f"line {expr.line}: '{op}' requires boolean operands, "
                                 f"got {lt} and {rt}")
        return dtypes.BOOL
    if op in COMPARISON_OPS:
        if not dtypes.comparable(lt, rt, op):
            raise TypeCheckError(f"line {expr.line}: cannot compare {lt} with {rt} using '{op}'")
        return dtypes.BOOL
    if op in ARITHMETIC_OPS:
        if not (dtypes.is_numeric(lt) and dtypes.is_numeric(rt)):
            raise TypeCheckError(f"line {expr.line}: '{op}' requires numeric operands, "
                                 f"got {lt} and {rt}")
        if op == "/":
            return dtypes.FLOAT
        return dtypes.numeric_result(lt, rt)
    raise AssertionError(f"unknown operator {op}")


def _infer_in(expr, schema, params):
    nt = infer(expr.needle, schema, params)
    ht = infer(expr.haystack, schema, params)
    if not (isinstance(expr.needle, Literal) and nt == dtypes.STRING):
        raise TypeCheckError(f"line {expr.line}: left side of 'in' must be a string literal")
    if not (isinstance(expr.haystack, ColumnRef) and ht == dtypes.STRING):
        raise TypeCheckError(f"line {expr.line}: right side of 'in' must be a string column")
    return dtypes.BOOL
"""Value types of the MTL type system."""
import re

INT = "int"
FLOAT = "float"
STRING = "string"
BOOL = "bool"
TIMESTAMP = "timestamp"

NUMERIC = frozenset({INT, FLOAT})


def is_numeric(t):
    return t in NUMERIC


def numeric_result(*types):
    """Result type of an int/float operation (int only if all operands are int)."""
    return INT if all(t == INT for t in types) else FLOAT


def comparable(a, b, op):
    """Whether values of types a and b may be compared with operator op."""
    if is_numeric(a) and is_numeric(b):
        return True
    if a != b:
        return False
    if a in (STRING, TIMESTAMP):
        return True
    if a == BOOL:
        return op in ("==", "!=")
    return False


_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$")
_BOOLS = {"true": True, "false": False}


def looks_like(text, t):
    """Whether stripped text is a valid literal of int, float or bool type."""
    if t == INT:
        return bool(_INT_RE.match(text))
    if t == FLOAT:
        return bool(_FLOAT_RE.match(text))
    if t == BOOL:
        return text.lower() in _BOOLS
    raise AssertionError(f"no text form check for {t}")


def parse_text(text, t):
    """Parse stripped text as an int, float or bool; raise ValueError when invalid."""
    if not looks_like(text, t):
        raise ValueError(f"not a valid {t}")
    if t == INT:
        return int(text)
    if t == FLOAT:
        value = float(text)
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError("not a finite number")
        return value
    return _BOOLS[text.lower()]
"""Resolution of schema blocks: inheritance, type overrides and calculated-field order."""
import copy

from . import dtypes
from .ast_nodes import ColumnRef
from .errors import DSLSyntaxError, TypeCheckError
from .typecheck import walk


class ResolvedField:
    """A schema field after inheritance; `visible` are the names its expression may use."""

    def __init__(self, name, field_type, expr, line, visible):
        self.name = name
        self.type = field_type
        self.expr = expr
        self.line = line
        self.visible = visible

    @property
    def is_calculated(self):
        return self.expr is not None


class ResolvedSchema:
    def __init__(self, name, fields):
        self.name = name
        self.fields = fields  # name -> ResolvedField, in declaration order
        self.calc_order = _calc_order(name, fields)

    @property
    def types(self):
        return {name: f.type for name, f in self.fields.items()}

    @property
    def physical(self):
        return {name: f.type for name, f in self.fields.items() if not f.is_calculated}


def override_allowed(old, new):
    """Same type, or numeric widening int -> float."""
    return old == new or (old == dtypes.INT and new == dtypes.FLOAT)


def resolve_all(decls):
    """Resolve every schema declaration; returns name -> ResolvedSchema."""
    resolved = {}
    for name in decls:
        _resolve(name, decls, resolved, [])
    return resolved


def _resolve(name, decls, resolved, stack):
    if name in resolved:
        return resolved[name]
    if name in stack:
        chain = " -> ".join(stack[stack.index(name):] + [name])
        raise DSLSyntaxError(f"circular schema inheritance: {chain}")
    decl = decls[name]
    fields = {}
    if decl.base is not None:
        if decl.base not in decls:
            raise DSLSyntaxError(f"line {decl.line}: schema '{name}' extends unknown "
                                 f"schema '{decl.base}'")
        base = _resolve(decl.base, decls, resolved, stack + [name])
        for fname, f in base.fields.items():
            fields[fname] = ResolvedField(f.name, f.type, copy.deepcopy(f.expr), f.line, f.visible)

    visible = set(fields)
    for f in decl.fields:
        if f.expr is not None:
            _check_references(f, visible, name)
        inherited = fields.get(f.name)
        if inherited is not None and not override_allowed(inherited.type, f.type):
            raise TypeCheckError(f"line {f.line}: schema '{name}' cannot override field "
                                 f"'{f.name}' from {inherited.type} to {f.type}")
        fields[f.name] = ResolvedField(f.name, f.type, f.expr, f.line, frozenset(visible))
        visible.add(f.name)

    result = ResolvedSchema(name, fields)
    resolved[name] = result
    return result


def _check_references(field, visible, schema_name):
    for node in walk(field.expr):
        if isinstance(node, ColumnRef) and node.name not in visible:
            raise DSLSyntaxError(f"line {field.line}: calculated field '{field.name}' in schema "
                                 f"'{schema_name}' references unknown or later-declared field "
                                 f"'{node.name}'")


def _calc_order(schema_name, fields):
    """Calculated fields ordered so each comes after the calculated fields it uses."""
    order = []
    state = {}

    def visit(f):
        mark = state.get(f.name)
        if mark == "done":
            return
        if mark == "active":
            raise DSLSyntaxError(f"line {f.line}: calculated field '{f.name}' in schema "
                                 f"'{schema_name}' depends on itself")
        state[f.name] = "active"
        for node in walk(f.expr):
            if isinstance(node, ColumnRef):
                dep = fields.get(node.name)
                if dep is not None and dep.is_calculated:
                    visit(dep)
        state[f.name] = "done"
        order.append(f)

    for f in fields.values():
        if f.is_calculated:
            visit(f)
    return order

"""Executes a type-checked Program over typed rows, producing ordered aggregated buckets."""
from datetime import datetime

from . import badrecords, dtypes
from .ast_nodes import Apply, Filter
from .aggregates import compute
from .errors import RuntimeFailure, TypeCheckError
from .evaluator import evaluate
from .timeutil import epoch_micros, format_utc, from_epoch_micros
from .typecheck import output_schema

_MICROS_PER_SECOND = 1_000_000


class Bucket:
    """One output record before formatting: window bounds, group key, aggregate values
    and post-aggregation calc values."""

    def __init__(self, window_start, window_end, group_key, values):
        self.window_start = window_start
        self.window_end = window_end
        self.group_key = group_key
        self.values = values
        self.calcs = {}


def run(program, records, schema_calcs=(), row_schema=None, sink=None):
    """Return the Buckets in normalized order, with post-agg calcs evaluated.

    `records` yields (Origin, row) pairs; `schema_calcs` are the using-schema's
    calculated fields in evaluation order; `row_schema` is the checked row
    typing (needed for post-agg calcs). Rows whose row-level evaluation fails
    are handed to `sink` (when given) and skipped.
    """
    rows = prepare_rows(program, schema_calcs, records, sink)
    buckets = sorted(_bucketize(program, rows), key=bucket_sort_key)
    if program.post_calcs:
        _post_aggregate(program, buckets, row_schema or {})
    return buckets


def prepare_rows(program, schema_calcs, records, sink=None):
    """Materialize calculated fields and run filter/apply statements row by row;
    returns the rows that survive the filters."""
    calcs = [(f.name, f.expr, f.type) for f in schema_calcs]
    calcs += [(c.name, c.expr, c.declared_type) for c in program.pre_calcs]
    result = []
    for origin, row in records:
        try:
            row = _evaluate_row(dict(row), calcs, program.row_ops)
        except (RuntimeFailure, ArithmeticError, ValueError, RecursionError) as exc:
            if sink is None:
                raise
            _reject(sink, origin, badrecords.RUNTIME_ERROR, exc, RuntimeFailure, row)
            continue
        except TypeError as exc:
            if sink is None:
                raise
            _reject(sink, origin, badrecords.TYPE_ERROR, exc, TypeCheckError, row)
            continue
        if row is not None:
            result.append(row)
    return result


def _evaluate_row(row, calcs, row_ops):
    """Return the transformed row, or None when a filter drops it (null counts as false)."""
    for name, expr, declared in calcs:
        row[name] = coerce(evaluate(expr, row), declared)
    for op in row_ops:
        if isinstance(op, Filter):
            if evaluate(op.predicate, row) is not True:
                return None
        elif isinstance(op, Apply):
            row[op.column] = evaluate(op.expr, row)
    return row


def _reject(sink, origin, error_type, exc, error_class, row):
    message = exc.message if isinstance(exc, RuntimeFailure) else (str(exc) or type(exc).__name__)
    if isinstance(exc, RecursionError):
        message = "expression nesting too deep"
    sink.reject(badrecords.BadRecord(origin, error_type, message,
                                     {"record": {k: _show(v) for k, v in row.items()}},
                                     error_class))


def _show(value):
    if isinstance(value, datetime):
        return format_utc(value)
    return value


def coerce(value, declared):
    """Widen int values of float-typed fields."""
    if declared == dtypes.FLOAT and isinstance(value, int) and not isinstance(value, bool):
        return float(value)
    return value


def _bucketize(program, rows):
    group_cols = program.group_columns
    window = program.window

    if not group_cols and window is None:
        return [Bucket(None, None, (), _aggregate(program, rows))]

    width = window.seconds * _MICROS_PER_SECOND if window else None
    buckets = {}
    for row in rows:
        start = None
        if width is not None:
            start = epoch_micros(row["timestamp"]) // width * width
        key = (start, tuple(row[c] for c in group_cols))
        buckets.setdefault(key, []).append(row)

    result = []
    for (start, group_key), bucket_rows in buckets.items():
        ws = we = None
        if start is not None:
            ws = from_epoch_micros(start)
            we = from_epoch_micros(start + width)
        result.append(Bucket(ws, we, group_key, _aggregate(program, bucket_rows)))
    return result


def _aggregate(program, rows):
    return {item.alias: compute(item, rows) for item in program.aggregate.items}


def bucket_sort_key(bucket):
    start = bucket.window_start
    window_part = (0,) if start is None else (1, start)
    return (window_part, tuple(_value_sort_key(v) for v in bucket.group_key))


def _value_sort_key(value):
    # Nulls sort first; within a column all non-null values share one kind.
    if value is None:
        return (0, 0)
    return (1, value)


def _post_aggregate(program, buckets, row_schema):
    """Evaluate post-agg calcs over the ordered buckets, one calc at a time."""
    types = output_schema(program, row_schema)
    frame_rows = []
    for bucket in buckets:
        row = {}
        if program.window is not None:
            row["window_start"] = bucket.window_start
            row["window_end"] = bucket.window_end
        row.update(zip(program.group_columns, bucket.group_key))
        row.update(bucket.values)
        frame_rows.append({name: coerce(value, types[name]) for name, value in row.items()})

    for calc in program.post_calcs:
        values = [coerce(evaluate(calc.expr, row, (frame_rows, idx)), calc.declared_type)
                  for idx, row in enumerate(frame_rows)]
        for row, bucket, value in zip(frame_rows, buckets, values):
            row[calc.name] = value
            bucket.calcs[calc.name] = value
"""Resolution of --input arguments (files, directories, globs) into an ordered file set."""
import glob
import os

from .errors import IOFailure

CSV = "csv"
TSV = "tsv"
PARQUET = "parquet"
AUTO = "auto"
FORMATS = (CSV, TSV, PARQUET, AUTO)

STDIN = "-"

_EXTENSIONS = (
    (".csv.gz", CSV), (".tsv.gz", TSV),
    (".csv", CSV), (".tsv", TSV), (".parquet", PARQUET),
)


class InputFile:
    """One file of the input set; `format` is None when it must be sniffed from content."""

    def __init__(self, path, file_format):
        self.path = path
        self.format = file_format


def format_from_name(name):
    """The format implied by a file name's extension (case-insensitive), or None."""
    lower = name.lower()
    for ext, fmt in _EXTENSIONS:
        if lower.endswith(ext):
            return fmt
    return None


def _has_extension(name):
    stem = name[:-3] if name.lower().endswith(".gz") else name
    return "." in stem.lstrip(".")


def resolve(patterns, recursive=False, forced=AUTO):
    """Return the union of files matched by all patterns, sorted by path.

    Explicit file paths are always used. Directory entries and glob matches
    are used when their extension is a supported one, or when they have no
    extension (their format is then forced by --format or sniffed).
    """
    forced = None if forced == AUTO else forced
    found = {}

    def add(path):
        display = os.path.normpath(path)
        key = os.path.realpath(path)
        if key not in found or display < found[key].path:
            fmt = format_from_name(os.path.basename(path)) or forced
            found[key] = InputFile(display, fmt)

    def add_candidate(path):
        name = os.path.basename(path)
        if name.startswith("."):
            return
        if format_from_name(name) is not None or not _has_extension(name):
            add(path)

    def add_directory(path):
        for entry in _scan(path, recursive):
            add_candidate(entry)

    stdin = None
    for pattern in patterns:
        if pattern == STDIN:
            stdin = InputFile(STDIN, forced or CSV)
        elif os.path.isdir(pattern):
            add_directory(pattern)
        elif os.path.exists(pattern):
            add(pattern)
        elif glob.has_magic(pattern):
            for match in sorted(glob.glob(pattern, recursive=recursive)):
                if os.path.isdir(match):
                    add_directory(match)
                elif os.path.isfile(match):
                    add_candidate(match)
        else:
            raise IOFailure(f"input '{pattern}' does not exist")

    files = sorted(found.values(), key=lambda f: f.path)
    if stdin is not None:
        files.insert(0, stdin)
    if not files:
        raise IOFailure("no input files matched: " + ", ".join(patterns))
    return files


def _scan(directory, recursive):
    try:
        if not recursive:
            names = sorted(os.listdir(directory))
            return [os.path.join(directory, n) for n in names
                    if os.path.isfile(os.path.join(directory, n))]
        result = []
        for root, dirs, names in os.walk(directory):
            dirs[:] = sorted(d for d in dirs if not d.startswith("."))
            result.extend(os.path.join(root, n) for n in sorted(names))
        return [p for p in result if os.path.isfile(p)]
    except OSError as exc:
        raise IOFailure(f"cannot list directory '{directory}': {exc}") from exc
"""Reads the input files (CSV/TSV, optionally gzipped, and Parquet) into typed rows.

Every value is checked against its expected type; rows that cannot be loaded
are handed to a BadRecordSink (which aborts the run in strict mode) instead
of being yielded.
"""
import csv
import gzip
import io
import sys
import zlib
from datetime import datetime, time, timedelta, timezone

from . import badrecords as br
from . import dtypes, inputs
from .badrecords import BadRecord, Origin
from .errors import IOFailure, TypeCheckError
from .timeutil import EPOCH

REQUIRED_COLUMNS = {
    "timestamp": dtypes.TIMESTAMP,
    "location": dtypes.STRING,
    "item": dtypes.STRING,
    "price": dtypes.FLOAT,
    "quantity": dtypes.FLOAT,
    "unit": dtypes.STRING,
    "category": dtypes.STRING,
}

# The event-time column: a row without a value for it is rejected.
EVENT_TIME = "timestamp"

DEFAULT_NULLS = ("", "null", "NULL", "NaN")

_GZIP_MAGIC = b"\x1f\x8b"
_PARQUET_MAGIC = b"PAR1"
_NAIVE_EPOCH = datetime(1970, 1, 1)


def parse_null_markers(spec):
    """--nulls value -> set of markers; the empty field is always null."""
    if spec is None:
        return frozenset(DEFAULT_NULLS)
    return frozenset({m.strip() for m in spec.split(",")} | {""})


def read_text(path):
    """Read a whole text file ('-' means STDIN), mapping failures to bad_io."""
    try:
        if path == "-":
            return sys.stdin.read()
        with open(path, "r", encoding="utf-8-sig", newline="") as fh:
            return fh.read()
    except (OSError, UnicodeDecodeError) as exc:
        raise IOFailure(f"cannot read '{path}': {exc}") from exc


class LoadContext:
    """Settings shared by all sources: timestamp parsing, null markers, strictness."""

    def __init__(self, ts_parser, null_markers, strict):
        self.ts_parser = ts_parser
        self.tz = ts_parser.default_tz
        self.null_markers = null_markers
        self.strict = strict

    def is_null_text(self, raw):
        return raw.strip() in self.null_markers


# --------------------------------------------------------------------------- sources


class TextSource:
    """A delimited file: header plus (line, fields) records; fields is None for a record
    the CSV reader could not parse (its error message is kept instead)."""

    kind = "text"

    def __init__(self, path, header, header_line, records):
        self.path = path
        self.header = header
        self.header_line = header_line
        self.records = records
        self.index = {name: idx for idx, name in enumerate(header)}

    @property
    def columns(self):
        return self.header


class ParquetSource:
    kind = "parquet"

    def __init__(self, path, table):
        self.path = path
        self.table = table
        self.columns = list(table.column_names)
        _check_columns(path, self.columns)


def open_sources(files):
    return [open_source(f) for f in files]


def open_source(input_file):
    path = input_file.path
    data = _read_bytes(path)
    fmt = input_file.format
    if fmt == inputs.PARQUET or (fmt is None and data.startswith(_PARQUET_MAGIC)):
        return _open_parquet(path, data)
    if data.startswith(_GZIP_MAGIC):
        try:
            data = gzip.decompress(data)
        except (OSError, EOFError, zlib.error) as exc:
            raise IOFailure(f"cannot decompress '{path}': {exc}") from exc
    text = data.decode("utf-8", "surrogateescape")
    if text.startswith("﻿"):
        text = text[1:]
    if fmt is None:
        first = text.split("\n", 1)[0]
        fmt = inputs.TSV if "\t" in first and "," not in first else inputs.CSV
    return _parse_delimited(path, text, "\t" if fmt == inputs.TSV else ",")


def _read_bytes(path):
    try:
        if path == inputs.STDIN:
            return sys.stdin.buffer.read()
        with open(path, "rb") as fh:
            return fh.read()
    except OSError as exc:
        raise IOFailure(f"cannot read '{path}': {exc}") from exc


def _open_parquet(path, data):
    try:
        import pyarrow as pa
        import pyarrow.parquet as pq
    except ImportError as exc:  # pragma: no cover - dependency is in requirements.txt
        raise IOFailure(f"cannot read Parquet '{path}': pyarrow is not installed") from exc
    try:
        table = pq.read_table(pa.BufferReader(data))
    except Exception as exc:  # pyarrow raises a variety of error types for corrupt files
        raise IOFailure(f"cannot read Parquet '{path}': {exc}") from exc
    return ParquetSource(path, table)


def _parse_delimited(path, text, delimiter):
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter, quotechar='"',
                        doublequote=True, strict=True)
    header = None
    header_line = None
    records = []
    prev = 0
    while True:
        try:
            record = next(reader)
            error = None
        except StopIteration:
            break
        except csv.Error as exc:
            record, error = None, str(exc)
        start, prev = prev + 1, reader.line_num
        if record is not None and _is_blank(record):
            continue
        if header is None:
            if record is None:
                raise IOFailure(f"malformed header in '{path}' line {start}: {error}")
            header, header_line = [h.strip() for h in record], start
            continue
        records.append((start, record, error))
    if header is None:
        raise IOFailure(f"'{path}' has no header row")
    _check_columns(path, header)
    return TextSource(path, header, header_line, records)


def _is_blank(record):
    return not record or (len(record) == 1 and not record[0].strip())


def _check_columns(path, names):
    seen = set()
    for name in names:
        if not name:
            raise IOFailure(f"'{path}' has an empty column name")
        if name in seen:
            raise IOFailure(f"'{path}' has duplicate column '{name}'")
        seen.add(name)


# --------------------------------------------------------------------------- schema


def infer_fields(sources, ctx):
    """Bare-statement typing: the Part 1 columns plus every other column found in any
    source, typed from its values (int, float, bool, else string).

    Returns (fields, lenient) where lenient names inferred string columns that
    accept any Parquet type (values are rendered as text).
    """
    extras = {}
    for source in sources:
        for name in source.columns:
            if name in REQUIRED_COLUMNS:
                continue
            if source.kind == "text":
                idx = source.index[name]
                found = _infer_text_type(
                    fields[idx] for _, fields, _ in source.records
                    if fields is not None and len(fields) == len(source.header)
                    and not ctx.is_null_text(fields[idx]))
            else:
                found = _ARROW_TO_DSL.get(_arrow_kind(source.table.schema.field(name).type),
                                          dtypes.STRING)
            extras[name] = _unify(extras.get(name), found)
    fields = dict(REQUIRED_COLUMNS)
    lenient = set()
    for name in sorted(extras):
        fields[name] = extras[name] or dtypes.STRING
        if fields[name] == dtypes.STRING:
            lenient.add(name)
    return fields, lenient


def _infer_text_type(values):
    present = [v.strip() for v in values]
    if not present:
        return None
    for t in (dtypes.INT, dtypes.FLOAT, dtypes.BOOL):
        if all(dtypes.looks_like(v, t) for v in present):
            return t
    return dtypes.STRING


def _unify(a, b):
    if a is None or a == b:
        return b
    if b is None:
        return a
    if dtypes.is_numeric(a) and dtypes.is_numeric(b):
        return dtypes.FLOAT
    return dtypes.STRING


# --------------------------------------------------------------------------- rows


class _Bad(Exception):
    def __init__(self, error_type, message):
        super().__init__(message)
        self.error_type = error_type
        self.message = message


def iter_rows(sources, fields, ctx, sink, lenient=()):
    """Yield (Origin, row) for every loadable row, in file then line order.

    `fields` maps field name -> DSL type; every row has all of them (absent
    columns are null). Rejected rows go to `sink`.
    """
    required = {EVENT_TIME} if fields.get(EVENT_TIME) == dtypes.TIMESTAMP else set()
    for source in sources:
        absent = [name for name in fields if name not in source.columns]
        if absent and ctx.strict:
            raise TypeCheckError(f"'{source.path}' is missing column(s): {', '.join(absent)}")
        if source.kind == "text":
            yield from _text_rows(source, fields, required, ctx, sink)
        else:
            yield from _parquet_rows(source, fields, required, ctx, sink, lenient)


def _text_rows(source, fields, required, ctx, sink):
    width = len(source.header)
    loaded = [(name, ftype, source.index.get(name)) for name, ftype in fields.items()]
    for line, record, error in source.records:
        origin = Origin(source.path, line=line)
        if record is None:
            sink.reject(BadRecord(origin, br.PARSE_TYPE_MISMATCH, f"malformed record: {error}",
                                  {"delimiter": _delimiter_name(source)}, IOFailure))
            continue
        if len(record) != width:
            error_type = br.MISSING_REQUIRED_FIELD if len(record) < width \
                else br.PARSE_TYPE_MISMATCH
            sink.reject(BadRecord(origin, error_type,
                                  f"record has {len(record)} fields, expected {width}",
                                  {"fields": record, "header": source.header}, IOFailure))
            continue
        row = {}
        for name, ftype, idx in loaded:
            raw = None if idx is None else record[idx]
            try:
                value = None if raw is None else _convert_text(raw, ftype, ctx)
                if value is None and name in required:
                    raise _Bad(br.MISSING_REQUIRED_FIELD,
                               f"required field '{name}' is "
                               + ("absent" if raw is None else "null"))
            except _Bad as bad:
                sink.reject(BadRecord(origin, bad.error_type,
                                      f"column '{name}': {bad.message}",
                                      {"column": name, "value": raw, "expected_type": ftype,
                                       "record": dict(zip(source.header, record))}))
                break
            row[name] = value
        else:
            yield origin, row


def _delimiter_name(source):
    return "tab" if source.path.lower().endswith((".tsv", ".tsv.gz")) else "comma"


def _convert_text(raw, ftype, ctx):
    text = raw.strip()
    if text in ctx.null_markers:
        return None
    if not raw.isascii() and any("\udc80" <= ch <= "\udcff" for ch in raw):
        raise _Bad(br.PARSE_TYPE_MISMATCH, "value is not valid UTF-8")
    if ftype == dtypes.STRING:
        return raw
    if ftype == dtypes.TIMESTAMP:
        try:
            return ctx.ts_parser.parse(text)
        except (ValueError, OverflowError) as exc:
            raise _Bad(br.TIMESTAMP_PARSE_ERROR,
                       f"invalid timestamp {raw!r}: {exc}") from exc
    if dtypes.is_numeric(ftype) and text.lower() == "nan":
        return None
    try:
        return dtypes.parse_text(text, ftype)
    except ValueError as exc:
        raise _Bad(br.PARSE_TYPE_MISMATCH, f"invalid {ftype} value {raw!r}: {exc}") from exc


# Parquet ------------------------------------------------------------------


_ARROW_TO_DSL = {
    "int": dtypes.INT,
    "float": dtypes.FLOAT,
    "decimal": dtypes.FLOAT,
    "bool": dtypes.BOOL,
    "string": dtypes.STRING,
    "binary": dtypes.STRING,
    "timestamp": dtypes.TIMESTAMP,
    "date": dtypes.TIMESTAMP,
    "null": None,
}

# DSL type -> Arrow kinds it accepts.
_ACCEPTS = {
    dtypes.INT: ("int",),
    dtypes.FLOAT: ("float", "int", "decimal"),
    dtypes.BOOL: ("bool",),
    dtypes.STRING: ("string", "binary"),
    dtypes.TIMESTAMP: ("timestamp", "date"),
}


def _arrow_kind(arrow_type):
    import pyarrow.types as pat

    if pat.is_dictionary(arrow_type):
        arrow_type = arrow_type.value_type
    checks = (
        ("bool", pat.is_boolean), ("int", pat.is_integer), ("float", pat.is_floating),
        ("decimal", pat.is_decimal), ("timestamp", pat.is_timestamp), ("date", pat.is_date),
        ("null", pat.is_null),
        ("string", lambda t: pat.is_string(t) or pat.is_large_string(t)
         or getattr(pat, "is_string_view", lambda _: False)(t)),
        ("binary", lambda t: pat.is_binary(t) or pat.is_large_binary(t)
         or pat.is_fixed_size_binary(t) or getattr(pat, "is_binary_view", lambda _: False)(t)),
    )
    for kind, check in checks:
        if check(arrow_type):
            return kind
    return "other"


def _parquet_rows(source, fields, required, ctx, sink, lenient):
    table = source.table
    columns = {}
    for name, ftype in fields.items():
        if name in source.columns:
            columns[name] = _parquet_column(table.column(name), ftype, ctx, name in lenient)
    for idx in range(table.num_rows):
        origin = Origin(source.path, row_index=idx)
        row = {}
        for name, ftype in fields.items():
            values = columns.get(name)
            value = None if values is None else values[idx]
            if value is None and name in required:
                value = _Bad(br.MISSING_REQUIRED_FIELD, f"required field '{name}' is "
                             + ("absent" if values is None else "null"))
            if isinstance(value, _Bad):
                sink.reject(BadRecord(origin, value.error_type,
                                      f"column '{name}': {value.message}",
                                      {"column": name, "value": getattr(value, "raw", None),
                                       "expected_type": ftype,
                                       "parquet_type": str(table.schema.field(name).type)
                                       if name in source.columns else None}))
                break
            row[name] = value
        else:
            yield origin, row


def _parquet_column(column, ftype, ctx, lenient):
    """Convert an Arrow column to Python values of `ftype`; failures become _Bad entries."""
    import pyarrow.types as pat

    arrow_type = column.type
    if pat.is_dictionary(arrow_type):
        column = column.cast(arrow_type.value_type)
        arrow_type = arrow_type.value_type
    kind = _arrow_kind(arrow_type)
    if kind == "null":
        return [None] * len(column)
    if kind not in _ACCEPTS[ftype]:
        if lenient:
            return [None if v is None else _as_text(v, ctx) for v in _pylist(column, kind, ctx)]
        return [None if v is None else _mismatch(v, arrow_type, ftype) for v in column.to_pylist()]
    values = _pylist(column, kind, ctx)
    if ftype == dtypes.STRING:
        return [None if isinstance(v, str) and ctx.is_null_text(v) else v for v in values]
    if ftype == dtypes.TIMESTAMP:
        return values
    if ftype == dtypes.FLOAT:
        return [_float_value(v) for v in values]
    return values


def _pylist(column, kind, ctx):
    import pyarrow as pa

    if kind == "timestamp":
        micros = column.cast(pa.int64()).to_pylist()
        return [None if v is None else _timestamp_value(v, column.type, ctx) for v in micros]
    values = column.to_pylist()
    if kind == "binary":
        return [None if v is None else _decode(v) for v in values]
    if kind == "date":
        return [None if v is None else _date_value(v, ctx) for v in values]
    return values


def _mismatch(value, arrow_type, ftype):
    bad = _Bad(br.PARQUET_TYPE_MISMATCH,
               f"Parquet type {arrow_type} cannot be read as {ftype} (value {value!r})")
    bad.raw = value
    return bad


def _as_text(value, ctx):
    if isinstance(value, _Bad):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, datetime):
        from .timeutil import format_utc
        return format_utc(value)
    text = str(value)
    return None if ctx.is_null_text(text) else text


def _decode(raw):
    try:
        return bytes(raw).decode("utf-8")
    except UnicodeDecodeError:
        bad = _Bad(br.PARQUET_TYPE_MISMATCH, "binary value is not valid UTF-8 text")
        bad.raw = repr(raw)
        return bad


def _float_value(value):
    if value is None or isinstance(value, _Bad):
        return value
    result = float(value)
    if result != result:
        return None  # NaN is a missing value
    if result in (float("inf"), float("-inf")):
        bad = _Bad(br.PARSE_TYPE_MISMATCH, f"non-finite float value {result}")
        bad.raw = repr(result)
        return bad
    return result


_UNIT_MICROS = {"s": (1_000_000, 1), "ms": (1000, 1), "us": (1, 1), "ns": (1, 1000)}


def _timestamp_value(raw, arrow_type, ctx):
    mul, div = _UNIT_MICROS[arrow_type.unit]
    micros = raw * mul // div
    try:
        if arrow_type.tz is not None:
            return EPOCH + timedelta(microseconds=micros)
        wall = _NAIVE_EPOCH + timedelta(microseconds=micros)
        return wall.replace(tzinfo=ctx.tz).astimezone(timezone.utc)
    except OverflowError:
        bad = _Bad(br.TIMESTAMP_PARSE_ERROR, f"timestamp value {raw} is out of range")
        bad.raw = raw
        return bad


def _date_value(value, ctx):
    try:
        return datetime.combine(value, time()).replace(tzinfo=ctx.tz).astimezone(timezone.utc)
    except OverflowError:
        bad = _Bad(br.TIMESTAMP_PARSE_ERROR, f"date value {value} is out of range")
        bad.raw = str(value)
        return bad

"""Row-level evaluation of type-checked expressions (nulls propagate SQL-style).

Post-aggregation expressions are evaluated with a frame: the ordered list of
output rows and the current index, which lag()/lead() navigate.
"""
import math
import operator

from . import casts, dtypes, functions
from .ast_nodes import Binary, Call, Cast, ColumnRef, InExpr, Literal, Unary
from .errors import RuntimeFailure

_COMPARE = {
    "<": operator.lt, "<=": operator.le, ">": operator.gt,
    ">=": operator.ge, "==": operator.eq, "!=": operator.ne,
}


def evaluate(expr, row, frame=None):
    if isinstance(expr, Literal):
        return expr.value
    if isinstance(expr, ColumnRef):
        return row[expr.name]
    if isinstance(expr, Binary):
        return _eval_binary(expr, row, frame)
    if isinstance(expr, Unary):
        value = evaluate(expr.operand, row, frame)
        if value is None:
            return None
        if expr.op == "!":
            return not value
        return -value if expr.op == "-" else value
    if isinstance(expr, InExpr):
        haystack = evaluate(expr.haystack, row, frame)
        if haystack is None:
            return None
        return evaluate(expr.needle, row, frame) in haystack
    if isinstance(expr, Cast):
        value = evaluate(expr.operand, row, frame)
        return casts.convert(value, expr.operand.type, expr.target, expr.line)
    if isinstance(expr, Call):
        return _check_finite(_eval_call(expr, row, frame), expr)
    raise AssertionError(f"unknown expression node {expr!r}")


def _eval_call(expr, row, frame):
    name = expr.name
    if name == "param":
        return expr.value
    if name == "coalesce":
        value = evaluate(expr.args[0], row, frame)
        if value is None or (isinstance(value, float) and math.isnan(value)):
            return evaluate(expr.args[1], row, frame)
        return value
    if name in functions.WINDOW_FUNCTIONS:
        return _eval_offset(expr, row, frame)
    args = [evaluate(a, row, frame) for a in expr.args]
    return functions.call(name, args)


def _eval_offset(expr, row, frame):
    """lag(expr, k) / lead(expr, k): the value of expr k rows before/after this one."""
    k = evaluate(expr.args[1], row, frame)
    if k is None or k <= 0:
        raise RuntimeFailure(f"line {expr.line}: {expr.name}() offset must be a positive "
                             f"integer, got {k}")
    rows, index = frame
    target = index - k if expr.name == "lag" else index + k
    if not 0 <= target < len(rows):
        return None
    return evaluate(expr.args[0], rows[target], (rows, target))


def _eval_binary(expr, row, frame):
    op = expr.op
    if op == "&":
        left = evaluate(expr.left, row, frame)
        if left is False:
            return False
        right = evaluate(expr.right, row, frame)
        if right is False:
            return False
        return None if left is None or right is None else True
    if op == "|":
        left = evaluate(expr.left, row, frame)
        if left is True:
            return True
        right = evaluate(expr.right, row, frame)
        if right is True:
            return True
        return None if left is None or right is None else False

    left = evaluate(expr.left, row, frame)
    right = evaluate(expr.right, row, frame)
    if left is None or right is None:
        return None
    if op in _COMPARE:
        return _COMPARE[op](left, right)
    return _check_finite(_arithmetic(op, left, right, expr), expr)


def _arithmetic(op, left, right, expr):
    try:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if right == 0:
            raise RuntimeFailure(f"line {expr.line}: division by zero")
        if op == "/":
            return left / right
        return left % right
    except OverflowError as exc:
        raise RuntimeFailure(f"line {expr.line}: numeric overflow") from exc


def _check_finite(value, expr):
    if isinstance(value, float) and not math.isfinite(value):
        raise RuntimeFailure(f"line {expr.line}: expression produced a non-finite number")
    if expr.type == dtypes.FLOAT and isinstance(value, int) and not isinstance(value, bool):
        try:
            return float(value)
        except OverflowError as exc:
            raise RuntimeFailure(f"line {expr.line}: numeric overflow") from exc
    return value
"""Explicit `cast(expr as type)` conversions: which are legal and how values convert."""
import math
from datetime import timedelta, timezone

from . import dtypes
from .errors import RuntimeFailure
from .timeutil import EPOCH, ONE_MICROSECOND, TimestampParser, format_utc

_ILLEGAL = {
    (dtypes.BOOL, dtypes.TIMESTAMP),
    (dtypes.TIMESTAMP, dtypes.BOOL),
}

# Parser used for string -> timestamp casts; the CLI installs one honouring --tz.
_timestamp_parser = TimestampParser(timezone.utc)


def set_timestamp_parser(parser):
    global _timestamp_parser
    _timestamp_parser = parser


def allowed(source, target):
    return (source, target) not in _ILLEGAL


def convert(value, source, target, line):
    """Convert a non-null value of type `source` to `target`; failures are runtime errors."""
    if value is None:
        return None
    if source == target:
        return value
    try:
        result = _convert(value, source, target)
    except (ValueError, OverflowError) as exc:
        raise RuntimeFailure(f"line {line}: cannot cast {_show(value)} "
                             f"from {source} to {target}: {exc}") from exc
    if isinstance(result, float) and not math.isfinite(result):
        raise RuntimeFailure(f"line {line}: cast produced a non-finite number")
    return result


def _convert(value, source, target):
    if target == dtypes.STRING:
        if source == dtypes.BOOL:
            return "true" if value else "false"
        if source == dtypes.TIMESTAMP:
            return format_utc(value)
        if source == dtypes.FLOAT:
            return repr(value)
        return str(value)
    if source == dtypes.STRING:
        if target == dtypes.TIMESTAMP:
            return _timestamp_parser.parse(value)
        return dtypes.parse_text(value.strip(), target)
    if target == dtypes.INT:
        if source == dtypes.TIMESTAMP:
            return (value - EPOCH) // timedelta(seconds=1)
        if source == dtypes.FLOAT:
            return math.trunc(value)
        return int(value)
    if target == dtypes.FLOAT:
        if source == dtypes.TIMESTAMP:
            return ((value - EPOCH) // ONE_MICROSECOND) / 1_000_000
        return float(value)
    if target == dtypes.BOOL:
        return value != 0
    if target == dtypes.TIMESTAMP:
        return EPOCH + timedelta(seconds=value)
    raise AssertionError(f"unhandled cast {source} -> {target}")


def _show(value):
    return repr(value) if isinstance(value, str) else str(value)
"""Rejected-row bookkeeping: classification, strict-mode termination and JSONL output."""
import json

from .errors import IOFailure, RuntimeFailure, TypeCheckError

PARSE_TYPE_MISMATCH = "PARSE_TYPE_MISMATCH"
TIMESTAMP_PARSE_ERROR = "TIMESTAMP_PARSE_ERROR"
RUNTIME_ERROR = "RUNTIME_ERROR"
TYPE_ERROR = "TYPE_ERROR"
MISSING_REQUIRED_FIELD = "MISSING_REQUIRED_FIELD"
PARQUET_TYPE_MISMATCH = "PARQUET_TYPE_MISMATCH"


class Origin:
    """Where a row came from: file path, 1-based line (text files) or row index (Parquet)."""

    def __init__(self, path, line=None, row_index=None):
        self.path = path
        self.line = line
        self.row_index = row_index

    def describe(self):
        if self.line is not None:
            return f"{self.path}:{self.line}"
        return f"{self.path} row {self.row_index}"

    def sort_key(self):
        return (self.path, self.line if self.line is not None else -1,
                self.row_index if self.row_index is not None else -1)


class BadRecord:
    def __init__(self, origin, error_type, message, context=None, error_class=None):
        self.origin = origin
        self.error_type = error_type
        self.message = message
        self.context = context or {}
        # The MTLError subclass raised for this record in strict mode.
        self.error_class = error_class or _DEFAULT_ERRORS[error_type]

    def to_json(self):
        return {
            "file": self.origin.path,
            "line": self.origin.line,
            "row_index": self.origin.row_index,
            "error_type": self.error_type,
            "error": self.error_type,
            "message": self.message,
            "context": self.context,
        }


_DEFAULT_ERRORS = {
    PARSE_TYPE_MISMATCH: TypeCheckError,
    TIMESTAMP_PARSE_ERROR: TypeCheckError,
    TYPE_ERROR: TypeCheckError,
    MISSING_REQUIRED_FIELD: TypeCheckError,
